import pandas as pd
for path in ['/root/ERP-2025-table10.xls','/root/ERP-2025-table12.xls']:
    df = pd.read_excel(path, sheet_name=0, header=None)
    print('\n',path)
    for i in range(len(df)):
        v = df.iloc[i,0]
        if isinstance(v,str) and ':' in v:
            print('first quarter row',i,v)
            break
    for i in range(len(df)-1,-1,-1):
        v = df.iloc[i,0]
        if isinstance(v,str) and ':' in v:
            print('last quarter row',i,v)
            break
